const __aivicBundle_70_assignPrioritiesToReminders = (() => {
  function assignPrioritiesToReminders(
    reportStatusList: Array<{
      employeeId?: string;
      userId?: string;
      employeeName?: string;
      name?: string;
      status?: 'submitted' | 'delayed' | 'not_submitted';
      submittedAt?: Date;
      delayedMinutes?: number;
    }>
  ): Array<{
    priority: number;
    employeeId?: string;
    userId?: string;
    employeeName?: string;
    name?: string;
    status: 'not_submitted' | 'delayed';
    reason?: string;
  }> {
    if (!reportStatusList || reportStatusList.length === 0) {
      return [];
    }
  
    const notSubmittedMembers: Array<{
      priority: number;
      employeeId?: string;
      userId?: string;
      employeeName?: string;
      name?: string;
      status: 'not_submitted' | 'delayed';
      reason?: string;
    }> = [];
  
    const delayedMembers: Array<{
      priority: number;
      employeeId?: string;
      userId?: string;
      employeeName?: string;
      name?: string;
      status: 'not_submitted' | 'delayed';
      reason?: string;
      delayedMinutes?: number;
      originalIndex?: number;
    }> = [];
  
    reportStatusList.forEach((member, index) => {
      if (member.status === 'not_submitted') {
        notSubmittedMembers.push({
          priority: 1,
          employeeId: member.employeeId,
          userId: member.userId,
          employeeName: member.employeeName,
          name: member.name,
          status: 'not_submitted',
          reason: 'Report not submitted',
        });
      } else if (member.status === 'delayed') {
        delayedMembers.push({
          priority: 2,
          employeeId: member.employeeId,
          userId: member.userId,
          employeeName: member.employeeName,
          name: member.name,
          status: 'delayed',
          reason: 'Report submitted late',
          delayedMinutes: member.delayedMinutes,
          originalIndex: index,
        });
      }
    });
  
    delayedMembers.sort((a, b) => {
      const delayDiff = (b.delayedMinutes ?? 0) - (a.delayedMinutes ?? 0);
      if (delayDiff !== 0) {
        return delayDiff;
      }
      return (a.originalIndex ?? 0) - (b.originalIndex ?? 0);
    });
  
    const result = [
      ...notSubmittedMembers,
      ...delayedMembers.map(({ originalIndex, delayedMinutes, ...rest }) => rest),
    ];
  
    return result;
  }
  return { assignPrioritiesToReminders };
})();
