    const elapsedMinutes = (currentTime.getTime() - lastPromptedAt.getTime()) / (1000 * 60);
    const nextPromptDueMinutes = promptIntervalMinutes - elapsedMinutes;
  
    const shouldEnd = nextPromptDueMinutes > 0;
